fn sha256_via_platform(
    path: &Path,
    layer: ManagedDiagnosticLayer,
) -> Result<String, ManagedLocalRuntimeError> {
    #[cfg(target_os = "windows")]
    let path_text = path.to_string_lossy();
    #[cfg(target_os = "windows")]
    let output = powershell_output_for(
        layer,
        "(Get-FileHash -Algorithm SHA256 -LiteralPath $args[0]).Hash",
        &[&path_text],
    )?;
    #[cfg(not(target_os = "windows"))]
    let output = Command::new("sha256sum")
        .arg(path)
        .output()
        .map_err(|error| ManagedLocalRuntimeError::new(layer, error.to_string()))?;
    if !output.status.success() {
        return Err(ManagedLocalRuntimeError::new(
            layer,
            format!("SHA-256 calculation failed: {}", command_output_text(&output)),
        ));
    }
    #[cfg(target_os = "windows")]
    let digest_text = decode_windows_command_text(&output.stdout);
    #[cfg(not(target_os = "windows"))]
    let digest_text = String::from_utf8_lossy(&output.stdout).into_owned();
    let digest = digest_text
        .split_whitespace()
        .next()
        .unwrap_or_default()
        .trim()
        .to_ascii_lowercase();
    if !is_sha256_hex(&digest) {
        return Err(ManagedLocalRuntimeError::new(
            layer,
            "SHA-256 calculation returned an invalid digest",
        ));
    }
    Ok(digest)
}

fn verify_file_sha256(
    path: &Path,
    expected: &str,
    layer: ManagedDiagnosticLayer,
) -> Result<(), ManagedLocalRuntimeError> {
    if !is_sha256_hex(expected) {
        return Err(ManagedLocalRuntimeError::new(
            layer,
            "expected SHA-256 digest is malformed",
        ));
    }
    let actual = sha256_via_platform(path, layer)?;
    if !actual.eq_ignore_ascii_case(expected) {
        return Err(ManagedLocalRuntimeError::new(
            layer,
            format!("SHA-256 mismatch: expected {expected}, observed {actual}"),
        ));
    }
    Ok(())
}

fn is_sha256_hex(value: &str) -> bool {
    value.len() == 64 && value.bytes().all(|byte| byte.is_ascii_hexdigit())
}

fn find_file_named(root: &Path, name: &str) -> Option<PathBuf> {
    let entries = fs::read_dir(root).ok()?;
    for entry in entries.flatten() {
        let path = entry.path();
        if path.is_file() && path.file_name().and_then(|value| value.to_str()) == Some(name) {
            return Some(path);
        }
        if path.is_dir()
            && let Some(found) = find_file_named(&path, name)
        {
            return Some(found);
        }
    }
    None
}

fn install_archive_into_wsl(
    archive_path: &Path,
    expected_sha256: &str,
) -> Result<(), ManagedLocalRuntimeError> {
    let remote_archive = format!(
        "/var/lib/gameengine/local-ai/cache/{}",
        pinned_asset_name(ManagedExecutionEnvironment::Wsl2Linux)
    );
    stream_file_into_wsl(archive_path, &remote_archive)?;
    verify_wsl_sha256(&remote_archive, expected_sha256)?;
    let runtime_root = format!(
        "/var/lib/gameengine/local-ai/runtime/{PINNED_LLAMA_CPP_TAG}"
    );
    let command = format!(
        "rm -rf {root}.staging; mkdir -p {root}.staging; tar -xzf {archive} -C {root}.staging; server=$(find {root}.staging -type f -name llama-server -print -quit); test -n \"$server\"; chmod +x \"$server\"; rm -rf {root}.rollback; if [ -d {root} ]; then mv {root} {root}.rollback; fi; if ! mv {root}.staging {root}; then if [ -d {root}.rollback ]; then mv {root}.rollback {root}; fi; exit 1; fi; final=$(find {root} -type f -name llama-server -print -quit); if [ -z \"$final\" ]; then rm -rf {root}; if [ -d {root}.rollback ]; then mv {root}.rollback {root}; fi; exit 1; fi; if [ \"$final\" != {root}/llama-server ]; then cp \"$final\" {root}/llama-server; chmod +x {root}/llama-server; fi",
        root = shell_quote(&runtime_root),
        archive = shell_quote(&remote_archive),
    );
    wsl_shell(&command, ManagedDiagnosticLayer::RuntimeArtifactIntegrity).map(|_| ())
}
